import app from 'flarum/forum/app';
import { extend, override } from 'flarum/common/extend';
import DiscussionControls from 'flarum/forum/utils/DiscussionControls';
import Button from 'flarum/common/components/Button';
import FieldSet from 'flarum/common/components/FieldSet';
import Select from 'flarum/common/components/Select';
import CookForSocialsModal from './components/CookForSocialsModal';
app.initializers.add('visualmulia-bali-nomads-premium', () => {
  // Retrieve Flarum core components from app.components
  const SettingsPage = app.components.SettingsPage;
  const WelcomeHero = app.components.WelcomeHero;
  const GlobalSearch = app.components.GlobalSearch;

  // 1. Social Curation Dashboard for Admins
  extend(DiscussionControls, 'moderationControls', function (items, discussion) {
    if (app.session.user && app.session.user.isAdmin()) {
      items.add('cook-for-socials', m(Button, {
        icon: "fas fa-tools",
        onclick: () => app.modal.show(CookForSocialsModal, {
          discussion
        })
      }, "\uD83D\uDD27 Cook for Socials"));
    }
  });

  // 2. Self-Selected Specialization Badge for Members (Settings Page integration)
  if (SettingsPage) {
    extend(SettingsPage.prototype, 'oninit', function () {
      this.selectedRole = '';
      app.request({
        method: 'GET',
        url: app.forum.attribute('apiUrl') + '/user-role'
      }).then(response => {
        if (response && response.data) {
          this.selectedRole = String(response.data.roleId || '');
          m.redraw();
        }
      });
    });
    extend(SettingsPage.prototype, 'settingsItems', function (items) {
      items.add('select-specialization', m(FieldSet, {
        className: "Settings-specialization",
        label: "Pilih Spesialisasi Peran Anda",
        style: "margin-top: 1.5rem; padding-top: 1.5rem; border-top: 1px solid var(--border-color);"
      }, m("div", {
        className: "helpText",
        style: "margin-bottom: 0.75rem; font-size: 0.9rem; color: #5f6862; font-weight: 500;"
      }, "Pilih spesialisasi Anda untuk menampilkan badge profesional resmi di samping profil Anda di forum Widatama."), Select.component({
        options: {
          '': 'Belum memilih / Hapus badge',
          '4': 'Developer (Software Engineer / Tech Builder)',
          '5': 'Marketer (Growth Hacker / Digital Marketer)',
          '6': 'Creator (Content Creator / Digital Designer)'
        },
        value: this.selectedRole || '',
        onchange: value => {
          this.selectedRole = value;
          this.saveRole(value);
        }
      })), 50); // High priority order placement
    });
    SettingsPage.prototype.saveRole = function (value) {
      app.alerts.dismiss(this.roleAlert);
      app.request({
        method: 'POST',
        url: app.forum.attribute('apiUrl') + '/user-role',
        body: {
          roleId: value
        }
      }).then(response => {
        app.alerts.show(this.roleAlert = {
          type: 'success'
        }, 'Spesialisasi peran berhasil diperbarui!');
        // Force reload the page after 1 second so the avatar/header badge displays the change immediately
        setTimeout(() => {
          window.location.reload();
        }, 1000);
      }).catch(err => {
        app.alerts.show(this.roleAlert = {
          type: 'error'
        }, 'Gagal memperbarui peran.');
      });
    };
  }

  // 3. Overhaul WelcomeHero to clean Giffgaff style with centered Big Search component
  if (WelcomeHero && GlobalSearch) {
    override(WelcomeHero.prototype, 'view', function (original) {
      if (this.hidden) return null;
      return m("header", {
        className: "Hero WelcomeHero GiffgaffHero"
      }, m("div", {
        className: "container"
      }, m(Button, {
        icon: "fas fa-times",
        className: "Hero-close Button Button--link",
        onclick: () => this.hide()
      }), m("div", {
        className: "containerNarrow Hero-content"
      }, m("h1", {
        className: "Hero-title"
      }, "Yuk, Cari Tahu Seputar AI & Produktivitas!"), m("p", {
        className: "Hero-subtitle"
      }, "Cari jawaban, tutorial, atau diskusikan ide SaaS Anda bersama ribuan builders lainnya."), m("div", {
        className: "Hero-search-wrapper"
      }, m(GlobalSearch, {
        state: app.search.state
      })))));
    });
  }
});